import React from "react";
import MemoryCard from "../components/MemoryCard";

const Dashboard = () => {

    const dummyMemories = [
        {
            text: "I am stressed about exams",
            importance: "High",
            expiry: "2 days"
        },
        {
            text: "I like pizza",
            importance: "Low",
            expiry: "1 day"
        }
    ];

    return (
        <div className="dashboard">
            <h2>Memory Dashboard 🧠</h2>

            {dummyMemories.map((mem, index) => (
                <MemoryCard key={index} memory={mem} />
            ))}

        </div>
    );
};

export default Dashboard;
